static void test_original_units_metric(){MetricFixture b;for(int i=0;i<2;++i){EventParameterBlock block;block.name="metric/"+std::to_string(i);block.values={1.,2.,3.};block.scales={.02,.2,.5};b.core.model.blocks.push_back(block);}ceres::Problem p;for(auto&block:b.core.model.blocks)p.AddResidualBlock(new MetricVectorResidual,nullptr,block.values.data());auto*x=b.core.model.blocks[0].values.data();auto*y=b.core.model.blocks[1].values.data();p.SetManifold(x,new ceres::SubsetManifold(3,{1}));const double inv=1./std::sqrt(2.);p.SetManifold(y,new JointLinearControlManifold({{"ambient_size",3},{"tangent_size",2},{"basis",{{inv,0.},{inv,0.},{0.,1.}}}}));const auto*oldx=p.GetManifold(x);const auto*oldy=p.GetManifold(y);const auto active=joint_gpu_ambient_activity(p,x,3);double before=0,after=0;require(p.Evaluate({},&before,nullptr,nullptr,nullptr),"original metric fixture cost invalid");JointSolverMetricV1 metric;const ceres::Manifold*cached=nullptr;for(int repeat=0;repeat<20;++repeat){const auto report=metric.prepare(b,p);require(p.Evaluate({},&after,nullptr,nullptr,nullptr)&&after==before,"numerical metric changed the actual objective value");require(joint_gpu_ambient_activity(p,x,3)==active&&joint_solver_original_manifold_v1(p.GetManifold(x))==oldx,"metric changed original fixed GPU ambient columns");if(cached)require(cached==p.GetManifold(x),"metric wrapper leaked a new Ceres manifold on each batch");cached=p.GetManifold(x);for(int bi=0;bi<2;++bi){auto&block=b.core.model.blocks[bi];auto*m=p.GetManifold(block.values.data());double J[6];require(m->PlusJacobian(block.values.data(),J),"physical unit chart Jacobian invalid");Eigen::Matrix<double,3,2>normalized;for(int a=0;a<3;++a)for(int t=0;t<2;++t)normalized(a,t)=J[a*2+t]/block.scales[a];require((normalized.transpose()*normalized-Eigen::Matrix2d::Identity()).cwiseAbs().maxCoeff()<1e-12,"original tangent did not consume the declared physical units");double d[2]={.03,-.07},next[3],back[2];require(m->Plus(block.values.data(),d,next)&&m->Minus(next,block.values.data(),back)&&std::abs(back[0]-d[0])<1e-12&&std::abs(back[1]-d[1])<1e-12,"scaled original chart Plus/Minus failed");if(bi==0)require(next[1]==block.values[1],"Subset fixed value changed by scaling");else require(std::abs((next[0]-next[1])-(block.values[0]-block.values[1]))<1e-12,"original linear control subspace was changed by units");}require(report.at("cached_original_chart_maps")==2,"metric cache grew without a graph/chart change");metric.restore(p);require(p.GetManifold(x)==oldx&&p.GetManifold(y)==oldy,"metric restore did not recover original manifolds");}ceres::Solver::Options options;JointSolverMetricV1::configure(options);require(!options.jacobi_scaling&&options.min_lm_diagonal==1.&&options.max_lm_diagonal==1.,"Jacobi or column-norm damping cancelled physical units");metric.retire_graph();double zero[2]={0.,0.},huge[2]={std::numeric_limits<double>::max(),0.},delta[2];JointSolverMetricManifoldV1 scaled(nullptr,{.02,.02},zero);require(!scaled.Minus(huge,zero,delta),"metric inverse overflow reported a finite step");JointSolverMetricManifoldV1 tiny(nullptr,{std::numeric_limits<double>::denorm_min(),1.},zero);double inverse[4];require(!tiny.MinusJacobian(zero,inverse),"metric inverse-Jacobian overflow reported success");}

